<script setup>
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { Head, Link, router } from '@inertiajs/vue3';
import { reactive } from 'vue';
import { useI18n } from '@/lib/i18n';
const { t }=useI18n();const props=defineProps({rows:Object,filters:Object});
const f=reactive({from:props.filters.from||'',to:props.filters.to||'',entity:props.filters.entity||''});
const apply=()=>router.get(route('audit.index'),f,{preserveState:true});
</script>
<template><Head :title="t('Activity history')" /><AuthenticatedLayout><div class="ops-page"><div class="ops-heading"><div><div class="eyebrow">{{ t('Administration') }}</div><h1>{{ t('Activity history') }}</h1><p>{{ t('Actions are recorded automatically. This view cannot change history.') }}</p></div></div><form class="panel p-4 mb-5 flex flex-wrap items-end gap-3" @submit.prevent="apply"><label class="text-xs text-gray-500">{{ t('From') }}<input v-model="f.from" type="date" class="search-field mt-2" /></label><label class="text-xs text-gray-500">{{ t('To') }}<input v-model="f.to" type="date" class="search-field mt-2" /></label><label class="text-xs text-gray-500">{{ t('Entity') }}<select v-model="f.entity" class="search-field mt-2"><option value="">{{ t('All') }}</option><option v-for="e in ['child','classroom','invoice','tuition_plan','incident','user']" :key="e" :value="e">{{ t(e) }}</option></select></label><button class="action-primary">{{ t('Apply') }}</button></form><section class="panel"><article v-for="r in rows.data" :key="r.id" class="p-5 border-b border-gray-100 flex flex-wrap justify-between gap-3 text-xs"><div class="min-w-0"><strong>{{ r.actor || t('System') }}</strong><span class="mx-2 text-green-700">{{ t(r.action) }}</span><span class="text-gray-400">{{ t(r.entity) }} #{{ r.entity_id }}</span><p class="text-gray-500 mt-2 break-words">{{ r.details }}</p></div><time class="text-gray-400" dir="ltr">{{ r.when }}</time></article><p v-if="!rows.data.length" class="empty-state">{{ t('No activity yet') }}</p><footer class="flex items-center justify-between gap-3 p-4 text-xs text-gray-500"><Link v-if="rows.prev_page_url" :href="rows.prev_page_url" class="action-secondary">{{ t('Previous') }}</Link><span>{{ rows.current_page }} / {{ rows.last_page }} · {{ rows.total }}</span><Link v-if="rows.next_page_url" :href="rows.next_page_url" class="action-secondary">{{ t('Next') }}</Link></footer></section></div></AuthenticatedLayout></template>
